import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"臨","description":"周易集解 - 臨","frontmatter":{"title":"臨","description":"周易集解 - 臨"},"headers":[],"relativePath":"zh/classics/jijie/019.md","filePath":"zh/classics/jijie/019.md"}'),l={name:"zh/classics/jijie/019.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="臨" tabindex="-1">臨 <a class="header-anchor" href="#臨" aria-label="Permalink to “臨”">​</a></h1><h2 id="臨-1" tabindex="-1">臨 <a class="header-anchor" href="#臨-1" aria-label="Permalink to “臨”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>臨，元亨利貞。至於八月有凶。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：有事而後可大，故受之以臨。臨者，大也。</p><p>崔憬曰：有蠱元亨，則可大之業成。故曰｢有事然後可大｣也。</p><p>虞翻曰：陽息至二，與遯旁通。剛浸而長，乾來交坤，動則成乾，故元亨利貞。</p><p>虞翻曰：與遯旁通，臨消於遯，六月卦也。於周為八月。遯弒君父，故至於八月有凶。荀公以兌為八月，兌於周為十月。言八月，失之甚矣。</p><p>鄭玄曰：臨，大也。陽氣自此浸而長大，陽浸長矣。而有四德，齊功於乾，盛之極也。人之情盛則奢淫，奢淫則將亡，故戒以凶。臨卦鬥建醜而用事，殷之正月也。當文王之時，紂為無道，故於是卦為殷家著興衰之戒，以見周改殷正之數雲。臨自周二月用事，訖其七月，至八月而遯卦受之，此終而復始，王命然矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：臨，剛浸而長。說而順，剛中而應。大亨以正，天之道也。至於八月有凶，消不久也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：剛，謂二也。兌為水澤，自下浸上，故浸而長也。</p><p>虞翻曰：說，兌。順，坤也。剛中，謂二也。四陰皆應之，故曰｢而應｣。大享以正，謂三動成乾。天得正為泰，天地交通。故｢亨以正，天之道也｣。</p><p>蜀才曰：此本坤卦。剛長而柔消，故大亨利正也。</p><p>案：臨十二月卦也。自建醜之月，至建申之月，凡閱八月，則成否也。否則天地不交，萬物不通，是至於八月有凶，斯之謂也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤上有地，臨。君子以教思無窮，容保民無疆。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：澤卑地高，高下相臨之象也。</p><p>君子以教思無窮，容保民無疆。</p><p>虞翻曰：君子，謂二也。震為言，兌口講習。學以聚之，問以辯之。坤為思，剛浸長，故｢以教思無窮｣。容，寬也。二寬以居之，仁以行之；坤為容民，故｢保民無疆｣矣。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，咸臨，貞吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：咸，感也。得正應四，故貞吉也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：咸臨貞吉，志行正也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：陽始咸升，以剛臨柔。得其正位而居，是吉。故曰志行正。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，咸臨，吉，無不利。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：得中多譽。兼有四陰。體復初。元吉。故無不利。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：咸臨吉，無不利，未順命也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：陽感至二，當升居五，群陰相承，故無不利也。陽當居五，陰當順從，今尚在二，故曰未順命也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，甘臨，無攸利，既憂之，無咎。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：甘臨，位不當也。既憂之，咎不長也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：兌為口，坤為土，土爰稼穡作甘。兌口銜坤，故曰甘臨。失位乘陽，故無攸利。言三失位無應，故憂之。動而成泰，故咎不可長也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，至臨，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：至，下也。謂下至初應，當位有實，故無咎。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：至臨無咎，當位實也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：四與二同功，欲升二至五，已得承順之，故曰至臨也。陽雖未乘，處位居正，故得無咎。是當位實也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，知臨，大君之宜，吉。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：大君之宜，行中之謂也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：五者，帝位。大君，謂二也。宜升上居五位，吉。故曰｢知臨，大君之宜｣也。二者處中，行升居五，五亦處中，故｢行中之謂也｣。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，敦臨，吉，無咎。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>荀爽曰：上應於三，欲因三升二，過應於陽，敦厚之意，故曰｢敦臨吉無咎｣。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：敦臨之吉，志在內也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：志在升二也。陰以陽為主。故志在內也。</p>',67)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
